import random, sys

TOP, BOTTOM, FULL = chr(9600), chr(9604), chr(9608)

sys.argv = ['snowstorm.py', '20']  # as if started with: python snowstorm.py 20
DENSITY = 4  # Default snow density is 4%
if len(sys.argv) > 1:
    DENSITY = int(sys.argv[1])

random.seed(12)
for y in range(6):
    for x in range(40):
        if random.randint(0, 99) < DENSITY:
            print(random.choice([TOP, BOTTOM]), end='')
        else:
            print(' ', end='')
    print()
print(FULL * 40)
print('density', DENSITY, '- change the 20 and run again')
